function renderPicker(){els.picker.innerHTML=Object.entries(processes).map(([k,p])=>`<button data-process="${k}" class="${k===state.key?'active':''}"><b>${p.title}</b><small>${p.result} · ${p.nodes.length} элементов</small></button>`).join('');$$('[data-process]').forEach(b=>b.onclick=()=>{state.key=b.dataset.process;state.selected=null;els.picker.classList.remove('open');render();fit(true);});}
