function renderSettings(p){$('#settingEvent').textContent=p.event||'Системное или ручное событие';$('#settingBranches').innerHTML=p.frames.map(f=>`<div class="setting-branch"><b>${f.title}</b><span>${f.condition}</span><span>Роли: ${[...new Set(p.nodes.filter(n=>n.branch===f.id).map(n=>n.owner))].join(', ')}</span></div>`).join('');}
