function nodeHTML(n){const dim=isDim(n)?' dim':'';const hi=!dim&&state.mode==='test'?' highlight':'';return `<article class="node ${n.type}${dim}${hi}" data-id="${n.id}" style="left:${n.x}px;top:${n.y}px;--node:${C[n.type]||C.task}"><span class="port in"></span><div class="node-body"><div class="node-type"><b>${icon[n.type]||'•'}</b>${typeName[n.type]||n.type}</div><div class="node-title">${n.title}</div></div><footer class="node-foot"><span title="Исполнитель и шаблон уведомления">🔔 ${n.owner}</span><b>${n.time}</b></footer><span class="port out"></span></article>`;}
