function defs(){return `<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="#8aa3b8"/></marker></defs>`;}
function edgePath(a,b){const aw=a.type==='decision'?144:(a.type==='start'||a.type==='end'?152:216);const ah=a.type==='decision'?144:(a.type==='start'||a.type==='end'?78:112);const bh=b.type==='decision'?144:(b.type==='start'||b.type==='end'?78:112);const x1=a.x+aw,y1=a.y+ah/2,x2=b.x,y2=b.y+bh/2;if(x2>x1+40){const m=(x1+x2)/2;return `M${x1},${y1} C${m},${y1} ${m},${y2} ${x2},${y2}`;}const loop=Math.max(x1,x2)+80;return `M${x1},${y1} C${loop},${y1} ${loop},${y2+95} ${x2},${y2}`;}
function renderEdges(p){const map=Object.fromEntries(p.nodes.map(n=>[n.id,n]));let s=defs();p.edges.forEach((e,i)=>{const a=map[e.from],b=map[e.to];if(!a||!b)return;const dim=isEdgeDim(e)?' dim':'';const d=edgePath(a,b);s+=`<path class="${e.tone||''}${dim}" d="${d}" data-edge="${i}"/>`;if(e.label){const x=(a.x+(a.type==='decision'?144:216)+b.x)/2,y=(a.y+b.y)/2+55;const w=Math.max(70,e.label.length*6.2+18);s+=`<g class="edge-label${dim}"><rect x="${x-w/2}" y="${y-13}" width="${w}" height="26"></rect><text x="${x}" y="${y}">${e.label}</text></g>`;}});els.svg.innerHTML=s;renderEdgeActions(p,map);}
function renderEdgeActions(p,map){els.edgeActions.innerHTML=p.edges.map((e,i)=>{const a=map[e.from],b=map[e.to];if(!a||!b||isEdgeDim(e))return'';const aw=a.type==='decision'?144:(a.type==='start'||a.type==='end'?152:216),ah=a.type==='decision'?144:(a.type==='start'||a.type==='end'?78:112),bh=b.type==='decision'?144:(b.type==='start'||b.type==='end'?78:112);const x=(a.x+aw+b.x)/2,y=(a.y+ah/2+b.y+bh/2)/2;return `<button class="edge-add" style="left:${x}px;top:${y}px" data-edge-add="${i}" title="Добавить действие в этот переход">+</button>`}).join('');$$('[data-edge-add]').forEach(b=>b.onclick=e=>{e.stopPropagation();state.edgeIndex=+b.dataset.edgeAdd;openCatalog('task','edge')});}
function startConnect(id){state.connectFrom=id;els.viewport.classList.add('connecting');renderNodes(processes[state.key]);toast('Выберите карточку, куда должен вести переход. Esc — отменить.');}
function isDim(n){if(state.mode!=='test')return false;if(n.branch!=='common'&&n.branch!==state.testBranch)return true;if(!n.outcomes.includes(state.testOutcome))return true;return false;}
function isEdgeDim(e){if(state.mode!=='test')return false;if(e.branch!=='common'&&e.branch!==state.testBranch)return true;if(e.outcome!=='any'&&e.outcome!==state.testOutcome)return true;return false;}
function renderBranches(p){const sel=$('#testBranch');sel.innerHTML=p.branches.map(([id,name])=>`<option value="${id}" ${state.testBranch===id?'selected':''}>${name}</option>`).join('');if(!p.branches.some(x=>x[0]===state.testBranch))state.testBranch=p.branches[0][0];}
function selectNode(id){
  state.selected=id;$$('.node').forEach(x=>x.classList.toggle('selected',x.dataset.id===id));
  const n=processes[state.key].nodes.find(x=>x.id===id);if(!n)return;
  const selectable=!!catalogs[n.type],source=n.catalogMeta||catalogNames[n.type]||'Объект процесса',objectId=n.catalogId||`${n.type}-${String(Math.abs(hashCode(n.title))).slice(0,4)}`;
  els.inspector.innerHTML=`<header><button data-close-inspector>×</button><small>${typeName[n.type]}</small><h3>${n.title}</h3></header>
    ${selectable?`<section><b>Объект из библиотеки</b><div class="object-link" style="margin-top:9px"><i>${icon[n.type]||'▣'}</i><span><b>${n.title}</b><small>${source} · ID ${objectId}</small></span><button id="replaceObject">Заменить</button></div></section>`:''}
    <section><label>Название размещения<input id="nodeTitleInput" value="${n.title}"></label><label>Исполнитель<select><option selected>${n.owner}</option><option>Сотрудник</option><option>Руководитель</option><option>Наставник</option><option>HR</option><option>Система</option></select></label><label>Когда создаётся<select><option>${n.time}</option><option>С открытием этапа</option><option>После предыдущего результата</option><option>За 3 дня до контрольной точки</option></select></label></section>
    <section><label>Шаблон уведомления · опционально<select><option>${n.notification}</option><option>Не отправлять</option><option>Назначено новое действие</option><option>Напомнить о сроке</option><option>Результат требует внимания</option></select></label><div class="explain">Уведомление привязано к событию этого действия. Получатели берутся из роли исполнителя и участников процесса.</div></section>
    <section><b>Что происходит дальше</b><div class="output-list">${outgoingFor(n.id).map(e=>`<div class="output ${e.tone||''}"><i>${e.tone==='negative'?'↻':'→'}</i><span>${e.label||'Перейти к следующему действию'}</span></div>`).join('')||'<div class="output"><span>Завершает маршрут</span></div>'}</div><button class="btn secondary" id="connectAction" style="width:100%;margin-top:10px">+ Добавить переход</button></section>`;
  els.inspector.classList.add('open');els.inspector.setAttribute('aria-hidden','false');$('[data-close-inspector]').onclick=closeInspector;$('#nodeTitleInput').onchange=e=>{n.title=e.target.value;renderNodes(processes[state.key]);renderEdges(processes[state.key]);};if($('#replaceObject'))$('#replaceObject').onclick=()=>openCatalog(n.type,'replace');$('#connectAction').onclick=()=>{closeInspector();startConnect(n.id)};
}
function hashCode(s){return [...s].reduce((a,c)=>((a<<5)-a)+c.charCodeAt(0),0)}
function outgoingFor(id){return processes[state.key].edges.filter(e=>e.from===id);}
function closeInspector(){els.inspector.classList.remove('open');els.inspector.setAttribute('aria-hidden','true');state.selected=null;}
function applyTransform(){els.world.style.transform=`translate(${state.tx}px,${state.ty}px) scale(${state.scale})`;$('#zoomValue').textContent=Math.round(state.scale*100)+'%';}
function fit(comfortable=false){const w=els.viewport.clientWidth,h=els.viewport.clientHeight,natural=Math.min(.78,(w-70)/5200,(h-70)/1500);state.scale=comfortable?Math.max(.48,Math.min(.60,natural*1.9)):natural;state.tx=comfortable?30:Math.max(28,(w-5200*state.scale)/2);state.ty=comfortable?36:Math.max(30,(h-1500*state.scale)/2);applyTransform();}
function setZoom(z,cx=els.viewport.clientWidth/2,cy=els.viewport.clientHeight/2){const old=state.scale;state.scale=Math.max(.35,Math.min(1.35,z));state.tx=cx-(cx-state.tx)*(state.scale/old);state.ty=cy-(cy-state.ty)*(state.scale/old);applyTransform();}
function startNodeDrag(e){if(state.mode!=='edit'||state.tool!=='select')return;const el=e.currentTarget,n=processes[state.key].nodes.find(x=>x.id===el.dataset.id);state.drag={kind:'node',n,sx:e.clientX,sy:e.clientY,ox:n.x,oy:n.y,moved:false};el.setPointerCapture(e.pointerId);}
window.addEventListener('pointermove',e=>{if(!state.drag)return;if(Math.abs(e.clientX-state.drag.sx)+Math.abs(e.clientY-state.drag.sy)>4)state.drag.moved=true;if(state.drag.kind==='node'){state.drag.n.x=Math.round(state.drag.ox+(e.clientX-state.drag.sx)/state.scale);state.drag.n.y=Math.round(state.drag.oy+(e.clientY-state.drag.sy)/state.scale);const el=$(`[data-id="${state.drag.n.id}"]`);el.style.left=state.drag.n.x+'px';el.style.top=state.drag.n.y+'px';renderEdges(processes[state.key]);}else{state.tx=state.drag.ox+(e.clientX-state.drag.sx);state.ty=state.drag.oy+(e.clientY-state.drag.sy);applyTransform();}});
window.addEventListener('pointerup',()=>{setTimeout(()=>state.drag=null,0);els.viewport.classList.remove('dragging');});
els.viewport.onpointerdown=e=>{if(e.target!==els.viewport&&e.target!==els.world&&e.target!==els.svg)return;if(state.tool==='hand'||e.target===els.viewport||e.target===els.world||e.target===els.svg){state.drag={kind:'pan',sx:e.clientX,sy:e.clientY,ox:state.tx,oy:state.ty,moved:false};els.viewport.classList.add('dragging');closeInspector();}};
els.viewport.addEventListener('wheel',e=>{e.preventDefault();if(e.ctrlKey){setZoom(state.scale*(e.deltaY>0?.92:1.08),e.clientX,e.clientY);}else{state.tx-=e.shiftKey?e.deltaY:e.deltaX;state.tx-=e.shiftKey?0:e.deltaY;state.ty-=e.deltaX?0:e.deltaY*.15;applyTransform();}},{passive:false});

function setMode(mode){state.mode=mode;$$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));els.test.classList.toggle('open',mode==='test');els.test.setAttribute('aria-hidden',mode!=='test');$('#settingsPanel').classList.toggle('open',mode==='settings');$('#settingsPanel').setAttribute('aria-hidden',mode!=='settings');closeInspector();renderNodes(processes[state.key]);renderEdges(processes[state.key]);if(mode==='test')runTest();}
function runTest(){state.testBranch=$('#testBranch').value;state.testOutcome=$('#testOutcome').value;renderNodes(processes[state.key]);renderEdges(processes[state.key]);const p=processes[state.key],name=p.branches.find(x=>x[0]===state.testBranch)?.[1];const count=p.nodes.filter(n=>!isDim(n)).length;$('#testSummary').innerHTML=`<b>${count} действий войдут в маршрут.</b><br>${name}. ${state.testOutcome==='success'?'Основной путь до результата.':'Показан возврат на корректирующее действие и повторная контрольная точка.'}`;}
function openBranchAI(branch){const p=processes[state.key],frame=p.frames.find(f=>f.id===branch);els.inspector.innerHTML=`<header><button data-close-inspector>×</button><small>AI подбор</small><h3>${frame.title}</h3></header><section><div class="explain">AI учитывает условие ветки «${frame.condition}», целевой результат процесса и уже добавленные действия.</div></section><section><b>Предлагает добавить</b><div class="output-list" style="margin-top:10px"><label class="output"><input type="checkbox" checked> Курс или материал из каталогов</label><label class="output"><input type="checkbox" checked> Практическая задача с проверкой</label><label class="output"><input type="checkbox" checked> Контрольная точка с руководителем</label></div><button class="btn primary" id="addSuggestions" style="width:100%;margin-top:14px">Добавить 3 элемента</button></section>`;els.inspector.classList.add('open');$('[data-close-inspector]').onclick=closeInspector;$('#addSuggestions').onclick=()=>{const existing=p.nodes.filter(n=>n.branch===branch),baseX=frame.x+60,baseY=frame.y+110,items=[['course','Стандарты и знания для роли','Сотрудник'],['task','Практическая задача по роли','Сотрудник'],['checkpoint','Подтвердить результат практики','Руководитель']],ids=[];items.forEach((it,i)=>{const id='ai'+Date.now()+i,n=N(id,it[0],it[1],baseX+(existing.length+i)*270,baseY,it[2],branch);n.catalogId=`ai-${i+1}`;n.catalogMeta=catalogNames[it[0]];p.nodes.push(n);ids.push(id)});if(existing.length){p.edges.push(E(existing.at(-1).id,ids[0],'AI дополнение',branch))}else{p.edges.push(E('d',ids[0],frame.title,branch))}p.edges.push(E(ids[0],ids[1]),E(ids[1],ids[2]));render();toast('AI добавил связанные объекты в ветку. Проверьте их перед публикацией.');closeInspector();};}
function toast(msg){els.toast.textContent=msg;els.toast.classList.add('show');setTimeout(()=>els.toast.classList.remove('show'),2600);}
function openCatalog(type='course',mode='add'){state.catalogType=catalogs[type]?type:'task';state.catalogMode=mode;$('#catalogTitle').textContent=mode==='replace'?'Замените объект':mode==='edge'?'Добавьте действие в переход':'Добавьте объект в процесс';$('#catalogSearch').value='';renderCatalog();$('#catalogModal').classList.add('open');$('#catalogModal').setAttribute('aria-hidden','false');$('#addMenu').classList.remove('open');}
function renderCatalog(){const types=Object.keys(catalogs);$('#catalogTypes').innerHTML=types.map(t=>`<button class="${t===state.catalogType?'active':''}" data-catalog-type="${t}"><span>${catalogNames[t]}</span><small>${catalogs[t].length}</small></button>`).join('');const q=$('#catalogSearch').value.toLowerCase();const items=catalogs[state.catalogType].filter(x=>(x[0]+x[1]+x[2]).toLowerCase().includes(q));$('#catalogList').innerHTML=items.map(x=>`<article class="catalog-item"><span class="catalog-icon">${icon[state.catalogType]||'▣'}</span><span><b>${x[1]}</b><small>${x[2]} · ID ${x[0]} · Опубликовано</small></span><button class="btn" data-pick-object="${x[0]}">${state.catalogMode==='replace'?'Выбрать':'Добавить'}</button></article>`).join('')||'<div class="settings-note">Ничего не найдено</div>';$$('[data-catalog-type]').forEach(b=>b.onclick=()=>{state.catalogType=b.dataset.catalogType;renderCatalog()});$$('[data-pick-object]').forEach(b=>b.onclick=()=>pickCatalogObject(b.dataset.pickObject));}
function pickCatalogObject(id){const item=catalogs[state.catalogType].find(x=>x[0]===id);if(!item)return;const p=processes[state.key];if(state.catalogMode==='replace'&&state.selected){const n=p.nodes.find(x=>x.id===state.selected);n.type=state.catalogType;n.title=item[1];n.catalogId=item[0];n.catalogMeta=item[2];renderNodes(p);renderEdges(p);selectNode(n.id);toast('Объект заменён, настройки размещения сохранены.');}
  else if(state.catalogMode==='edge'&&p.edges[state.edgeIndex]){const edge=p.edges[state.edgeIndex],a=p.nodes.find(x=>x.id===edge.from),b=p.nodes.find(x=>x.id===edge.to),nid='new'+Date.now();const n=N(nid,state.catalogType,item[1],Math.round((a.x+b.x)/2),Math.round((a.y+b.y)/2+85),'Сотрудник',edge.branch);n.catalogId=item[0];n.catalogMeta=item[2];p.nodes.push(n);p.edges.splice(state.edgeIndex,1,E(edge.from,nid,edge.label,edge.branch,edge.outcome,edge.tone),E(nid,edge.to,'',edge.branch,edge.outcome,edge.tone));renderNodes(p);renderEdges(p);selectNode(nid);toast('Действие добавлено в переход.');}
  else{addNodeFromCatalog(state.catalogType,item)}closeCatalog();}
function addNodeFromCatalog(type,item){const p=processes[state.key],id='new'+Date.now(),n=N(id,type,item[1],Math.round((els.viewport.clientWidth/2-state.tx)/state.scale),Math.round((els.viewport.clientHeight/2-state.ty)/state.scale),'Сотрудник');n.catalogId=item[0];n.catalogMeta=item[2];p.nodes.push(n);renderNodes(p);renderEdges(p);selectNode(id);toast('Объект добавлен. Соедините его с маршрутом через порт +.');}
