function openWizard(){const p=processes[state.key],empty=state.key==='draft';wizardStep=2;$('#aiModal h2').textContent=empty?'Собрать процесс с AI':'Дополнить текущий процесс с AI';$('#aiModal header p').textContent=empty?'AI соберёт этапы, подберёт объекты из каталогов и создаст переходы внутри уже заданных веток.':'AI учитывает текущие ветки, условия, роли и уже добавленные действия. Выберите, где найти пробелы.';$('.branch-cards').innerHTML=p.frames.map(f=>`<label><input type="checkbox" checked><span><b>${f.title}</b><small>${f.condition}</small></span></label>`).join('');$('.source-check').innerHTML=`<input type="checkbox" checked> ${empty?'Подобрать курсы, статьи, тесты, опросы, задачи и контрольные точки из доступных библиотек':'Найти пропуски в последовательности, подобрать элементы из каталога и предложить переходы по результатам'}`;syncWizard();$('#aiModal').classList.add('open');$('#aiModal').setAttribute('aria-hidden','false');}
